import pytest
import numpy as np

from ATARVA.sub_operation_utils import encode_methylation

def get_cg_positions(sequence):
    arr  = np.frombuffer(sequence.upper().encode(), dtype=np.uint8)
    c_mask = arr[:-1] == ord('C')
    g_mask = arr[1:]  == ord('G') 
    return np.where(c_mask & g_mask)[0]

